// ── Centipede split-on-death ──────────────────────────────────────────

/**
 * Promote a body segment to a new centipede head.
 * Adds Brain + AggroState (hunting, pointed at killer) + SoundEmitter + Wounds.
 * Re-indexes the remaining tail-side chain.
 */
function promoteToHead(world, newHeadId, killerId) {
  const seg = world.get(newHeadId, CentipedeSegment);
  if (!seg) return;

  // Update segment metadata
  seg.index = 0;
  seg.headId = 0;  // self is head
  seg.prevId = 0;  // no predecessor

  // New chain ID
  const newChainId = ((world.step * 0x9e3779b9) ^ (newHeadId * 0x517cc1b7)) >>> 0;
  seg.chainId = newChainId;

  // Re-index tail-side chain
  let cursor = seg.nextId;
  let idx = 1;
  while (cursor && world.isAlive(cursor)) {
    const cSeg = world.get(cursor, CentipedeSegment);
    if (!cSeg) break;
    cSeg.headId = newHeadId;
    cSeg.index = idx++;
    cSeg.chainId = newChainId;
    cursor = cSeg.nextId;
  }

  // Grant full AI components to the new head
  if (!world.has(newHeadId, Brain)) {
    try { world.add(newHeadId, Brain, {
      learnedSpellIds: [], itemKnowledgeIdentities: [],
      seenTiles: new Uint8Array(), intelligence: 2, visionRange: 8,
    }); } catch { /* already present */ }
  }

  // Start hunting, pointed toward the killer
  let lkx = 0, lky = 0;
  if (killerId && world.isAlive(killerId)) {
    const kp = world.get(killerId, Position);
    if (kp) { lkx = kp.x | 0; lky = kp.y | 0; }
  }
  if (!world.has(newHeadId, AggroState)) {
    try { world.add(newHeadId, AggroState, {
      alertLevel: AGGRO_LEVELS.hunting,
      lastKnownX: lkx, lastKnownY: lky,
      searchTurnsLeft: SEARCH_TURNS_HUNTING_GRACE,
      retreating: false, patrolDx: 0, patrolDy: 0,
    }); } catch { /* already present */ }
  }

  if (!world.has(newHeadId, SoundEmitter)) {
    try { world.add(newHeadId, SoundEmitter, { ambient: 30, lastActionNoise: 0 }); } catch {}
  }
  if (!world.has(newHeadId, Wounds)) {
    try { world.add(newHeadId, Wounds, { list: [] }); } catch {}
  }

  world.emit("centipede:split", { newHeadId });
}

/**
 * When any centipede segment dies, unlink it and promote the tail-side
 * to an independent centipede.
 */
export function centipedeSplitOnDeath() {
  return (ctx) => {
    const world = ctx.world;
    const deadId = ctx.deadId;
    const seg = world.get(deadId, CentipedeSegment);
    if (!seg) return;

    const prevId = seg.prevId;
    const nextId = seg.nextId;

    // Unlink dead segment from its neighbors
    if (prevId && world.isAlive(prevId)) {
      const prevSeg = world.get(prevId, CentipedeSegment);
      if (prevSeg) prevSeg.nextId = 0;
    }
    if (nextId && world.isAlive(nextId)) {
      const nextSeg = world.get(nextId, CentipedeSegment);
      if (nextSeg) nextSeg.prevId = 0;
    }

    // Promote tail-side to a new independent centipede
    if (nextId && world.isAlive(nextId)) {
      promoteToHead(world, nextId, ctx.killer);
    }
  };
}
      const slot = slots[i % slots.length];
      world.add(itemId, Position, { x: slot.x, y: slot.y });
    }
    made++;
  }

  if (made <= 0) return false;
  world.emit?.("npc:dialogue", {
    actor: targetId,
    targetId: actorId,
    text: "Ratatoskr shakes impossible treasure out of his tail.",
  });
  world.emit?.("shop:open", {
    actor: actorId,
    targetId,
    buyMarkup: 3.0,
    sellDiscount: 0.15,
    vendorKind: "travellingVendor",
    vendorLabel: "Ratatoskr",
  });
  return true;
}

export function acceptRatatoskrBargain(world, actorId, targetId) {
  const ratPos = world.get(targetId, Position);
  const actorPos = world.get(actorId, Position);
  const depth = Math.max(8, currentDepth(world, 0) || 8);
  const rng = createRng(seedFor(world, targetId, 0xbadf00d));
  const itemId = shopStock.generateRatatoskrLegendaryItem(world, depth, rng);
  if (!(itemId > 0)) return false;

  try {
    world.add(itemId, Beatitude, { state: "cursed" });
  } catch {
    const beat = world.get(itemId, Beatitude);
    if (beat) beat.state = "cursed";
  }

  const info = world.get(itemId, ItemInfo);
  if (info) {
    world.mutate(itemId, ItemInfo, rec => {
      rec.identified = true;
      rec.value = Math.max(Number(rec.value || 0) | 0, 1);
    });
  }

  applyStatusEffect(world, actorId, {
    key: "cursed",
    turnsLeft: 666,
    potency: 2,
    stacks: 1,
    sourceId: targetId,
    sourceKind: "ratatoskr",
    sourceKey: "branch_bargain",
  });

  if (!addToInventory(world, actorId, itemId, { mergeCompatible: false })) {
    const drop = actorPos || ratPos || { x: 0, y: 0 };
    world.add(itemId, Position, { x: drop.x | 0, y: drop.y | 0 });
  }

  world.emit?.("npc:dialogue", {
    actor: targetId,
    targetId: actorId,
    text: "Done. One root remembers your name now. Try not to dream downward.",
  });
  world.emit?.("status", {
    id: actorId,
    kind: "curse",
    effect: "cursed",
    text: "A bargain takes root under your skin.",
  });
  return true;
}

export function registerRatatoskrDialog() {
  registerDialog({
    id: "norse:ratatoskr",
    start: "root",
    maxDistance: 2,
    nodes: {
      root: {
        text: "Ratatoskr chatters in three directions at once. 'Up-root news, down-root slander, middle-root bargains. Choose quickly; I owe an eagle an insult.'",
        choices: [
          {
            id: "open_cache",
            label: "Show me the impossible cache.",
            onSelect: (ctx) => openRatatoskrCache(ctx.world, ctx.actorId, ctx.targetId),
            close: true,
          },
          {
      turnsRemaining: Math.max(0, remaining),
      transitionCooldown: cooldown,
    });

    // Gameplay effects during rain
    const isRaining = current === "rain" || current === "heavy_rain";
    if (isRaining) {
      _extinguishPlayer(world);
      _extinguishFloorFireHazards(world);
      _extinguishStructures(world);
      _waterCrops(world);
      _emitRainAmbient(world, current);
    }
    if (current === "heavy_rain") {
      _rollLightning(world);
    }

    break; // singleton
  }
}

/**
 * Rain removes active floor fire hazards before they can continue spreading.
 */
function _extinguishFloorFireHazards(world) {
  const toDestroy = [];
